From c31ee795f7059edcdc42355ed84ed4f6c91a8e1d Mon Sep 17 00:00:00 2001
From: Morris Jette <jette@schedmd.com>
Date: Thu, 28 Apr 2016 07:30:41 -0700
Subject: [PATCH] Correction to task binding

This fixes a problem introduced in commit
31aa3244b55bcf6fafe8d76a2c3b8047afeac6e3
which was causing test1.91 to generate a fatal slurmd error.

diff --git a/src/plugins/task/affinity/dist_tasks.c b/src/plugins/task/affinity/dist_tasks.c
index 62c46d4ae9..5bc1eda1e2 100644
--- a/src/plugins/task/affinity/dist_tasks.c
+++ b/src/plugins/task/affinity/dist_tasks.c
@@ -1157,8 +1157,9 @@ static int _task_layout_lllp_block(launch_tasks_request_msg_t *req,
 				continue;

 			sock_inx = i / pu_per_socket;
-			if (socket_tasks[sock_inx] >= req->ntasks_per_socket)
-				continue;  /* Default ntasks_per_socket = INFINITE */
+			if ((req->ntasks_per_socket != 0) &&
+			    (socket_tasks[sock_inx] >= req->ntasks_per_socket))
+				continue;
 			socket_tasks[sock_inx]++;

 			if (!masks[taskcount])
@@ -1196,6 +1197,8 @@ static int _task_layout_lllp_block(launch_tasks_request_msg_t *req,
 			if (++taskcount >= max_tasks)
 				break;
 		}
+		for (i = 0; i < hw_sockets; i++)
+			socket_tasks[i] = 0;
 	}
 	xfree(socket_tasks);

-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an incorrect condition in the task allocation logic that failed to properly check if the number of tasks per socket had reached the specified limit, leading to potential over-allocation of tasks and a fatal error in the slurmd service. The original code only accounted for an infinite number of tasks per socket, neglecting cases where a finite limit was set, which resulted in exceeding the allowed task count.

        Commit message:
        Correction to task binding

This fixes a problem introduced in commit
31aa3244b55bcf6fafe8d76a2c3b8047afeac6e3
which was causing test1.91 to generate a fatal slurmd error.  

        Patch:
          */
 static int _task_layout_lllp_block(launch_tasks_request_msg_t *req,
 				   uint32_t node_id, bitstr_t ***masks_p)
 {
 	int c, i, size, last_taskcount = -1, taskcount = 0;
 	uint16_t hw_sockets = 0, hw_cores = 0, hw_threads = 0;
 	int max_tasks = req->tasks_to_launch[(int)node_id];
 	int max_cpus = max_tasks * req->cpus_per_task;
 	bitstr_t *avail_map;
 	bitstr_t **masks = NULL;
 	int sock_inx, pu_per_socket, *socket_tasks = NULL;

 	info("_task_layout_lllp_block ");

 	avail_map = _get_avail_map(req, &hw_sockets, &hw_cores, &hw_threads);
 	if (!avail_map) {
 		return SLURM_ERROR;
 	}

 	size = bit_set_count(avail_map);
 	if (size < max_tasks) {
 		error("task/affinity: only %d bits in avail_map for %d tasks!",
 		      size, max_tasks);
 		FREE_NULL_BITMAP(avail_map);
 		return SLURM_ERROR;
 	}
 	if (size < max_cpus) {
 		/* Possible result of overcommit */
 		i = size / max_tasks;
 		info("task/affinity: reset cpus_per_task from %d to %d",
 		     req->cpus_per_task, i);
 		req->cpus_per_task = i;
 	}
 	size = bit_size(avail_map);

 	if ((req->cpu_bind_type & CPU_BIND_ONE_THREAD_PER_CORE) &&
 	    (max_cpus > (hw_sockets * hw_cores))) {
 		/* More CPUs requested than available cores,
 		 * disable core-level binding */
 		req->cpu_bind_type &= (~CPU_BIND_ONE_THREAD_PER_CORE);
 	}

 	*masks_p = xmalloc(max_tasks * sizeof(bitstr_t*));
 	masks = *masks_p;

 	pu_per_socket = hw_cores * hw_threads;
 	socket_tasks = xmalloc(hw_sockets);

 	/* block distribution with oversubsciption */
 	c = 0;
 	while (taskcount < max_tasks) {
 		if (taskcount == last_taskcount) {
 			fatal("_task_layout_lllp_block infinite loop");
 		}
 		last_taskcount = taskcount;
 		/* the abstract map is already laid out in block order,
 		 * so just iterate over it
 		 */
 		for (i = 0; i < size; i++) {
 			/* skip unavailable resources */
 			if (bit_test(avail_map, i) == 0)
 				continue;

 			sock_inx = i / pu_per_socket;
-			if (socket_tasks[sock_inx] >= req->ntasks_per_socket)
-				continue;  /* Default ntasks_per_socket = INFINITE */
+			if ((req->ntasks_per_socket != 0) &&
+			    (socket_tasks[sock_inx] >= req->ntasks_per_socket))
+				continue;
 			socket_tasks[sock_inx]++;

 			if (!masks[taskcount])
 				masks[taskcount] = bit_alloc(
 					conf->block_map_size);
 			//info("setting %d %d", taskcount, i);
 			bit_set(masks[taskcount], i);

 			/* skip unrequested threads */
 			if (req->cpu_bind_type & CPU_BIND_ONE_THREAD_PER_CORE)
 				i += hw_threads - 1;

 			if (++c < req->cpus_per_task)
 				continue;
 			/* Means we are binding to cores so skip the
 			   rest of the threads in this one.  If a user
 			   requests ntasks-per-core=1 and the
 			   cpu_bind=threads this will not be able to
 			   work since we don't know how many tasks per
 			   core have been allocated.
 			*/
 			if (!(req->cpu_bind_type & CPU_BIND_ONE_THREAD_PER_CORE)
 			    && ((req->cpu_bind_type & CPU_BIND_TO_CORES)
 				|| (req->ntasks_per_core == 1))) {
 				int threads_not_used;
 				if (req->cpus_per_task < hw_threads)
 					threads_not_used =
 						hw_threads - req->cpus_per_task;
 				else
 					threads_not_used =
 						req->cpus_per_task % hw_threads;
 				i += threads_not_used;
 			}
 			c = 0;
 			if (++taskcount >= max_tasks)
 				break;
 		}
+		for (i = 0; i < hw_sockets; i++)
+			socket_tasks[i] = 0;
 	}
 	xfree(socket_tasks);

 	/* last step: expand the masks to bind each task
 	 * to the requested resource */
 	_expand_masks(req->cpu_bind_type, max_tasks, masks,
 			hw_sockets, hw_cores, hw_threads, avail_map);
 	FREE_NULL_BITMAP(avail_map);

 	return SLURM_SUCCESS;
 }



